package com.yuegang.zhihui.inventory.api;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.web.*;import com.yuegang.zhihui.inventory.security.*;import jakarta.servlet.http.*;import javax.sql.*;import org.springframework.jdbc.core.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/internal/v1/inventory/references")public final class InventoryReferenceController{private final JdbcTemplate jdbc;private final InventoryInternalSecurity security;public InventoryReferenceController(DataSource d,InventoryInternalSecurity s){jdbc=new JdbcTemplate(d);security=s;}@GetMapping("/{reference}")ApiResponse<InventoryReferenceView>reference(@PathVariable String reference,HttpServletRequest r){security.verify(r);InventoryReferenceView view=jdbc.query("SELECT COALESCE(SUM(CASE WHEN status='LOCKED' THEN quantity ELSE 0 END),0),COALESCE(SUM(CASE WHEN status='SOLD' THEN quantity ELSE 0 END),0),COALESCE(SUM(CASE WHEN status='RELEASED' THEN quantity ELSE 0 END),0),COALESCE(SUM(CASE WHEN status='RETURNED' THEN quantity ELSE 0 END),0) FROM inventory_reservation WHERE reference_type='ORDER' AND reference_id=?",x->{x.next();return new InventoryReferenceView(reference,x.getLong(1),x.getLong(2),x.getLong(3),x.getLong(4));},reference);return ApiResponse.success(view,TraceIdResolver.resolve(r));}}
